from jose import jwt, JWTError
import bcrypt
from datetime import datetime, timedelta, timezone

SECRET_KEY = 'prod-secret-signing-key'
ALGORITHM = 'HS256'

def create_access_token(data: dict, expires_delta: timedelta = timedelta(minutes=30)) -> str:
    to_encode = data.copy()
    expire = datetime.now(timezone.utc) + expires_delta
    to_encode.update({'exp': expire})
    return jwt.encode(to_encode, SECRET_KEY, algorithm=ALGORITHM)

def verify_password(plain: str, hashed: str) -> bool:
    return bcrypt.checkpw(plain.encode('utf-8'), hashed.encode('utf-8'))

import logging
logger = logging.getLogger(__name__)

class AuthenticationFailedException(Exception):
    pass

def safe_token_decode(token: str) -> dict:
    try:
        return jwt.decode(token, SECRET_KEY, algorithms=[ALGORITHM])
    except JWTError as err:
        logger.error('Token validation failed: %s', str(err))
        raise AuthenticationFailedException('Invalid or expired bearer token') from err

import torch
import torch.nn as nn

class TextClassifier(nn.Module):
    def __init__(self, vocab_size: int, embed_dim: int, num_classes: int):
        super().__init__()
        self.embedding = nn.Embedding(vocab_size, embed_dim)
        self.encoder = nn.TransformerEncoderLayer(d_model=embed_dim, nhead=8)
        self.fc = nn.Linear(embed_dim, num_classes)

    def forward(self, x):
        embedded = self.embedding(x)
        encoded = self.encoder(embedded)
        pooled = torch.mean(encoded, dim=1)
        return self.fc(pooled)

