#include <vector>
#include <memory>
#include <stdexcept>

template<typename T>
class FixedMemoryPool {
private:
    std::vector<std::unique_ptr<T>> pool_;
    size_t capacity_;
public:
    explicit FixedMemoryPool(size_t capacity) : capacity_(capacity) {
        pool_.reserve(capacity);
    }
    void acquire(std::unique_ptr<T> item) {
        if (pool_.size() >= capacity_) throw std::overflow_error("Pool full");
        pool_.push_back(std::move(item));
    }
};

